function shotVideoTarget(){return shotMode==='clips'?data.shotScript?.generation_clips?.[clipIndex]:data.shots?.[si];}
const videoBusy=job=>['preparing','queued','running','waiting','saving','stopping'].includes(job?.status);
function selectedShotVideo(target){const versions=(target.videoVersions||[]).filter(v=>!v.deleted_at&&!data.deletedVideoIds?.includes(v.id));return versions.find(v=>v.id===target.activeVideoId)||versions.at(-1);}
function applyShotVideo(target,job){if(job.deleted_at||data.deletedVideoIds?.includes(job.id))return;if(job.first_frame_auto_image&&(!target.frameImages?.first?.activeId||target.frameImages.first.autoFromPrevious)){target.frameImages??={};target.frameImages.first={...(target.frameImages.first||{}),versions:[job.first_frame_auto_image],activeId:job.first_frame_auto_image.id,sourceChoice:'previous',needsReview:false,autoFromPrevious:true};}target.videoJob=job;if(job.status==='completed')target.activeVideoId=job.id;target.videoVersions??=[];const existing=target.videoVersions.findIndex(v=>v.id===job.id);if(existing>=0)target.videoVersions[existing]={...target.videoVersions[existing],...job};if(job.status==='completed'&&!target.videoVersions.some(v=>v.id===job.id)){target.videoVersions.push(job);target.activeVideoId=job.id;}save();}
async function requestShotVideo(target,draft=false){if(!draft&&videoBusy(target.videoJob)){toast('这个镜头或片段已有生成任务');return}let prepared;try{prepared=typeof shotGenerationInputs==='function'?shotGenerationInputs(target):null;}catch(e){toast(e.message);return;}const references=shotResolvedReferences(target);if(!prepared&&references.some(ref=>!ref.item)){toast('请先补齐缺少的参考图片');return}const prompt=prepared?prepared.prompt:target.clip_id?(target.custom_video_prompt||target.video_prompt):target.video_generation?.prompt;if(!prompt?.trim()){toast('请填写视频提示词');return}const resolution=ShotAspect.video(target,data);const[width,height]=resolution.split('x').map(Number);const id=crypto.randomUUID();const inputs={request_id:id,preview_only:draft,project_id:data.project_id,target_id:target.shot_id||target.clip_id,target_type:target.clip_id?'clip':'shot',port:(typeof videoGenerationPort==='function'?videoGenerationPort():Number(localStorage.getItem('frame-comfy-port')||8188)),duration:Number(target.duration),width,height,prompt,picture_inputs:references.map(r=>({picture:r.picture,type:r.type,ref_id:r.ref_id,image_url:r.item?.url,version_id:r.item?.id}))};if(prepared)Object.assign(inputs,prepared);if(!draft){target.videoJob={id,status:'preparing',created_at:new Date().toISOString(),port:inputs.port,duration:inputs.duration,steps:inputs.video_quality==='pika_flex'?6:inputs.video_quality==='quality'?25:inputs.video_quality==='quality12'?12:4};const oldTiming=document.querySelector('#videoTiming');if(oldTiming)oldTiming.innerHTML='<b>准备并上传参考图片</b><p>采样尚未开始</p>';save();render();if(typeof fillVideoTiming==='function')fillVideoTiming();}try{const job=await frontFetch('/api/video',inputs);if(draft){const url='/api/open-workflow/'+job.id+'?kind=video&port='+inputs.port;const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.textContent='打开已准备好的视频工作流 ↗';a.style.color='var(--green)';document.querySelector('#shotVideoDraft').after(a);a.click();toast('视频工作流已准备，未提交生成');}else{applyShotVideo(target,job);render();toast('已提交 '+(target.shot_id||target.clip_id)+' 视频任务')}}catch(error){if(!draft){target.videoJob={id,status:'failed',error:error.message};save();render();}toast(error.message)}}
const shotsBeforeVideo=shots;
shots=function(){shotsBeforeVideo();const target=shotVideoTarget();if(!target)return;const cards=document.querySelectorAll('.shot-script-editor > .card');if(cards.length<2)return;const parent=cards[1];const job=target.videoJob,version=selectedShotVideo(target),busy=videoBusy(job),box=document.createElement('section');box.id='shotVideoPanel';box.innerHTML=`<div class="divider"></div><div class="preview-head"><b>${target.clip_id?'片段':'当前镜头'}视频 · MiniMax H3</b><span class="subtle">${target.duration} 秒</span></div>${version?`<div id="shotVideoPlayerSlot"></div><p class="subtle">当前播放版本：${version.width||"?"} × ${version.height||"?"} px；下方尺寸用于下一次生成。</p>`:'<p class="subtle">生成后在这里播放，声音使用 H3 原生输出。</p>'}${ShotAspect.mismatch(version,data)?'<p class="notice">当前旧视频与项目画幅不符，请重新生成。修改尺寸不会改变已有视频。</p>':''}<label>视频尺寸 · ${ShotAspect.ratio(data)}<select id="shotVideoSize" aria-label="视频尺寸">${ShotAspect.options(data)}</select></label><label>生成模式<select id="shotVideoQuality" aria-label="视频生成模式"><option value="pika_flex">Pika Flex · 六步 · 原生声音</option><option value="fast">加速模式 · 使用加速 LoRA（多图4步 / 首尾帧8步）</option><option value="quality12">标准模式 · 12步 · 不使用加速 LoRA</option><option value="quality">标准模式 · 25步 · 不使用加速 LoRA</option></select></label><button id="shotVideoGenerate" class="primary wide" ${busy?'disabled':''}>${busy?'正在生成…':version?'重新生成视频':target.clip_id?'生成这个片段视频':'生成这个镜头视频'}</button>${busy&&job?.id?'<button id="shotVideoStop">停止生成</button>':''}<p id="shotVideoStatus" class="subtle" role="status">${esc(job?({preparing:'正在准备并上传参考图',queued:'已进入 ComfyUI 队列',running:'H3 正在生成视频',waiting:'等待 ComfyUI 返回结果',cancelled:'已停止生成',stopping:'正在停止生成',completed:'视频已保存到本机',failed:'生成失败：'+job.error})[job.status]||job.status:'只提交当前镜头或片段，不会批量生成。')}</p><button id="shotVideoDraft" class="wide">在 ComfyUI 中打开当前视频工作流</button><div id="shotVideoLinks" style="display:flex;gap:12px;flex-wrap:wrap;margin:12px 0"></div><div class="history">${(target.videoVersions||[]).map((v,i)=>`<button data-video-version="${esc(v.id)}" class="${version?.id===v.id?'primary':''}">${v.experiment_label?esc(v.experiment_label):'V'+(i+1)} · ${esc(generationGpuLabel(v))} · ${esc(new Date(v.finished_at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}))}</button>`).join('')}</div><p class="subtle">本机 H3 · 可选标准12步、标准25步或加速模式。按上方 Picture 顺序连接，不要求先生成首帧。短镜头会先生成不少于5秒的素材，再裁切到所设时长。多镜头片段的切镜时间仍需人工检查。</p>`;parent.append(box);if(version)StableShotPlayer.mount(box.querySelector('#shotVideoPlayerSlot'),target,version);document.querySelector('#shotVideoSize').value=ShotAspect.video(target,data);document.querySelector('#shotVideoSize').onchange=e=>{target.videoResolution=e.target.value;save();render()};document.querySelector('#shotVideoSize').disabled=busy;const quality=document.querySelector('#shotVideoQuality');quality.value=target.videoQuality||'pika_flex';quality.disabled=busy;quality.onchange=e=>{target.videoQuality=e.target.value;save();render();};document.querySelector('#shotVideoGenerate').onclick=()=>requestShotVideo(target);document.querySelector('#shotVideoStop')?.addEventListener('click',async e=>{e.target.disabled=true;try{const stopped=await frontFetch('/api/video/'+target.videoJob.id+'/cancel',{project_id:data.project_id,target_id:target.shot_id||target.clip_id});applyShotVideo(target,stopped);render();toast(stopped.status==='stopping'?'正在停止，请稍候':'已停止，恢复为可重新生成');}catch(error){toast(error.message);e.target.disabled=false;}});document.querySelector('#shotVideoDraft').onclick=()=>requestShotVideo(target,true);box.querySelectorAll('[data-video-version]').forEach(button=>button.onclick=()=>{target.activeVideoId=button.dataset.videoVersion;save();render()});if((target.videoVersions||[]).some(v=>v.status==='completed')){const remove=document.createElement('button');remove.type='button';remove.textContent='删除本镜视频';remove.style.color='#e8bcb9';remove.disabled=busy;remove.onclick=async()=>{if(!confirm('删除本镜已生成的视频记录？删除后一键生成会重新处理本镜。'))return;remove.disabled=true;try{if(typeof flushDisk==='function')await flushDisk();if(typeof diskConflict!=='undefined'&&diskConflict)throw Error('请先读取最新项目后再删除');const projectId=data.project_id,result=await frontFetch('/api/video/delete-shot',{project_id:projectId,target_id:target.shot_id||target.clip_id,confirm:true});if(data.project_id!==projectId)return;Object.assign(data,result.project);if(typeof diskRevision!=='undefined')diskRevision=result.revision;if(typeof lastDiskData!=='undefined')lastDiskData=JSON.stringify(data);if(typeof browserSave==='function')browserSave();videoBatchPreview=null;render();toast('本镜视频记录已删除，可重新生成');}catch(e){toast(e.message);remove.disabled=false;}};box.querySelector('.history').before(remove);}const links=document.querySelector('#shotVideoLinks'),workflow=busy&&job.prompt_id?job:version||job;if(workflow?.prompt_id){for(const[label,url]of [['打开本次视频工作流','/api/open-workflow/'+workflow.id+'?kind=video&port='+workflow.port],['下载视频工作流','/api/video/'+workflow.id+'/workflow?download=1']]){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.textContent=label;a.style.color='var(--green)';links.append(a)}}if(version){const a=document.createElement('a');a.href=version.video_url+'?download=1';a.textContent='下载 MP4';a.style.color='var(--green)';links.append(a)}parent.querySelectorAll('p').forEach(p=>{if(p.textContent.includes('首帧和视频生成尚未接入'))p.textContent='首帧图像生成待接入；下方可用 H3 多图参考直接生成视频。'});};
let pollingShotVideo=false;setInterval(async()=>{if(pollingShotVideo)return;pollingShotVideo=true;let changed=false;try{for(const target of [...(data.shots||[]),...(data.shotScript?.generation_clips||[]),...(data.shotScriptArchives||[]).flatMap(a=>[...(a.shots||[]),...(a.shotScript?.generation_clips||[])])]){if(!['preparing','queued','running','waiting','saving','stopping'].includes(target.videoJob?.status))continue;try{const previousStatus=target.videoJob.status;const job=await frontFetch('/api/video/'+target.videoJob.id);applyShotVideo(target,job);if(previousStatus!==job.status)changed=true;}catch(error){target.videoJob.connection_error=error.message;}}if(changed&&(tab===2||tab===4)){const panel=document.querySelector('#shotVideoPlayerSlot video');if(!panel||panel.paused)render();else{const status=document.querySelector('#shotVideoStatus');if(status)status.textContent='视频状态已更新，切换镜头后查看。';}}}finally{pollingShotVideo=false}},5000);
const stageBeforeShotVideos=stage;stage=function(){if(tab!==4){stageBeforeShotVideos();return}const clips=data.shotScript?.generation_clips||[];document.querySelector('#panel').innerHTML='<div class="section-head"><div><h3>视频与原生声音</h3><p>选择片段进入生成设置，检查参考图与对白后提交到本机 H3。</p></div></div><div class="shot-reference-grid">'+clips.map((c,i)=>{const v=selectedShotVideo(c);return '<div class="card"><b>'+esc(c.clip_id)+' · '+c.duration+' 秒</b><p class="subtle">'+esc(c.shot_ids.join(' + '))+'</p>'+(v?'<video controls preload="metadata" src="'+esc(v.video_url)+'" style="width:100%;background:#080d14"></video>':'<p class="subtle">'+(c.videoJob?'任务状态：'+esc(c.videoJob.status):'尚未生成')+'</p>')+'<button data-open-video-clip="'+i+'">进入片段生成</button></div>'}).join('')+'</div>'+(!clips.length?'<div class="card">请先导入分镜 JSON。</div>':'');document.querySelectorAll('[data-open-video-clip]').forEach(b=>b.onclick=()=>{clipIndex=Number(b.dataset.openVideoClip);shotMode='clips';tab=2;render()});};render();
